/* CraftedSoft: site behaviour (no dependencies). Pages are static HTML generated by tools/build.mjs;
   this file adds interaction: theme and colour scheme, header menus, reveal-on-scroll, the Delog-style
   3D effects (stage, tilt cards, coverflow, compare slider, count-up numbers), doors, FAQ and the form. */
;(function () {
  const SITE = window.CS_SITE || { contact: {}, products: [] }
  const C = SITE.contact || {}
  const doc = document.documentElement
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches
  const hoverable = matchMedia('(hover: hover) and (pointer: fine)').matches
  const $ = (s, r = document) => r.querySelector(s)
  const $$ = (s, r = document) => [...r.querySelectorAll(s)]
  const root = doc.dataset.root || ''
  const store = { get: (k) => { try { return localStorage.getItem(k) } catch (e) { return null } }, set: (k, v) => { try { v == null ? localStorage.removeItem(k) : localStorage.setItem(k, v) } catch (e) { /* storage blocked */ } } }

  /* ---------- Opened straight from disk (file://) ----------
     Clean folder links (about/, products/chittill/) need a web server to open their index.html; from disk the
     browser shows a file listing instead. So on file:// only, point those links at the folder's index.html. */
  const LOCAL = location.protocol === 'file:'
  const toFile = (href) => {
    if (!LOCAL || /^([a-z]+:|#|\/\/)/i.test(href)) return href
    const m = href.match(/^([^?#]*)(.*)$/)
    return m[1] === '' || m[1].endsWith('/') ? `${m[1] || './'}index.html${m[2]}` : href
  }
  if (LOCAL) $$('a[href]').forEach((a) => { const h = a.getAttribute('href'); const t = toFile(h); if (t !== h) a.setAttribute('href', t) })
  const quiet = (vt) => { if (vt) ['ready', 'finished', 'updateCallbackDone'].forEach((k) => vt[k]?.catch?.(() => {})) }
  addEventListener('pagereveal', (e) => quiet(e.viewTransition))
  addEventListener('pageswap', (e) => quiet(e.viewTransition))

  /* ---------- Clean addresses: a #fragment never stays in the address bar ---------- */
  const LEGACY = { about: 'about/', commitments: 'about/', services: 'services/', process: 'services/' }
  if (location.hash) {
    const id = decodeURIComponent(location.hash.slice(1))
    const target = document.getElementById(id)
    if (!target && LEGACY[id]) { location.replace(toFile(root + LEGACY[id])); return }
    history.replaceState(history.state, '', location.pathname + location.search)
    if (target) requestAnimationFrame(() => target.scrollIntoView({ block: 'start', behavior: 'instant' }))
  }
  document.addEventListener('click', (e) => {
    const a = e.target.closest && e.target.closest('a[href^="#"]')
    if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey) return
    const target = document.getElementById(a.getAttribute('href').slice(1))
    if (!target) return
    e.preventDefault()
    target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' })
    if (a.classList.contains('skip')) { target.setAttribute('tabindex', '-1'); target.focus({ preventScroll: true }) }
  })

  /* ---------- Reveal on scroll (anything already on screen at load shows at once) ---------- */
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target) }
  }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' })
  $$('.reveal').forEach((el, i) => {
    if (el.getBoundingClientRect().top < innerHeight) { el.classList.add('no-anim', 'in'); return }
    el.style.transitionDelay = `${Math.min(i % 4, 3) * 70}ms`
    io.observe(el)
  })
  requestAnimationFrame(() => requestAnimationFrame(() => $$('.no-anim').forEach((el) => el.classList.remove('no-anim'))))

  /* ---------- Theme (light / dark) ---------- */
  const setTheme = (t, save) => {
    doc.dataset.theme = t
    const meta = $('meta[name="theme-color"]')
    if (meta) meta.content = t === 'dark' ? '#050506' : '#ffffff'
    if (save) store.set('cs-theme', t)
    $$('.theme-btn').forEach((b) => { const l = t === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'; b.setAttribute('aria-label', l); b.title = l })
  }
  setTheme(doc.dataset.theme || 'light', false)
  $$('.theme-btn').forEach((b) => b.addEventListener('click', () => {
    const next = doc.dataset.theme === 'dark' ? 'light' : 'dark'
    if (document.startViewTransition && !reduced) document.startViewTransition(() => setTheme(next, true))
    else setTheme(next, true)
  }))
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => { if (!store.get('cs-theme')) setTheme(e.matches ? 'dark' : 'light', false) })

  /* ---------- Colour scheme (theme.schemes in site-data.js) ---------- */
  const picks = $$('[data-scheme-pick]')
  const defScheme = (SITE.theme && SITE.theme.scheme) || 'mono'
  const markScheme = (id) => picks.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.schemePick === id)))
  const setScheme = (id) => {
    const apply = () => { doc.dataset.scheme = id; markScheme(id) }
    if (document.startViewTransition && !reduced) document.startViewTransition(apply)
    else apply()
    store.set('cs-scheme', id === defScheme ? null : id)
  }
  markScheme(doc.dataset.scheme || defScheme)
  document.addEventListener('click', (e) => {
    const b = e.target.closest && e.target.closest('[data-scheme-pick], [data-scheme-reset]')
    if (b) setScheme(b.dataset.schemePick || defScheme)
  })
  const popMenu = (btn, pop, onOpen) => {
    if (!btn || !pop) return () => {}
    const show = (v) => { pop.hidden = !v; btn.setAttribute('aria-expanded', String(v)); if (v && onOpen) onOpen() }
    btn.addEventListener('click', (e) => { e.stopPropagation(); show(pop.hidden) })
    document.addEventListener('click', (e) => { if (!pop.hidden && !btn.parentElement.contains(e.target)) show(false) })
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && !pop.hidden) { show(false); btn.focus() } })
    return show
  }
  popMenu($('.schbtn'), $('#schpop'))

  /* ---------- Header: glass once scrolled, phone menu, products menu ---------- */
  const nav = $('#hdr')
  if (nav) {
    const onScroll = () => nav.classList.toggle('is-scrolled', scrollY > 8)
    onScroll()
    addEventListener('scroll', onScroll, { passive: true })
    const burger = $('.nav-menu', nav)
    burger?.addEventListener('click', () => { const open = nav.classList.toggle('open'); burger.setAttribute('aria-expanded', String(open)) })
    $$('.mnav a', nav).forEach((a) => a.addEventListener('click', () => { nav.classList.remove('open'); burger?.setAttribute('aria-expanded', 'false') }))
    addEventListener('resize', () => { if (innerWidth > 960 && nav.classList.contains('open')) { nav.classList.remove('open'); burger?.setAttribute('aria-expanded', 'false') } })
  }
  $$('.pmenu').forEach((menu) => {
    const items = $$('.pmenu-item', menu)
    const panes = $$('.pmenu-pane', menu)
    const select = (i) => { items.forEach((x, n) => x.classList.toggle('sel', n === i)); panes.forEach((p, n) => (p.hidden = n !== i)) }
    items.forEach((x, i) => { x.addEventListener('mouseenter', () => select(i)); x.addEventListener('focus', () => select(i)) })
    // Opens on a different product than the page you're on, so the menu shows something new.
    const here = menu.dataset.here != null ? Number(menu.dataset.here) : -1
    const start = Math.max(0, items.findIndex((_, i) => i !== here))
    popMenu($('.pmenu-btn', menu), $('.pmenu-panel', menu), () => select(start))
    menu.addEventListener('keydown', (e) => {
      if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return
      e.preventDefault()
      const now = items.indexOf(document.activeElement)
      items[now < 0 ? 0 : (now + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus()
    })
  })

  /* ---------- Hero 3D stage follows the pointer ---------- */
  const stage = $('[data-tilt-stage]')
  if (stage && !reduced) {
    let raf = 0
    addEventListener('pointermove', (e) => {
      cancelAnimationFrame(raf)
      raf = requestAnimationFrame(() => {
        stage.style.setProperty('--mx', (e.clientX / innerWidth - 0.5).toFixed(3))
        stage.style.setProperty('--my', (e.clientY / innerHeight - 0.5).toFixed(3))
      })
    })
  }

  /* ---------- Tilt cards (with a light that follows the pointer) ---------- */
  if (!reduced && hoverable) {
    $$('[data-tilt]').forEach((el) => {
      el.addEventListener('pointermove', (e) => {
        const r = el.getBoundingClientRect()
        const x = (e.clientX - r.left) / r.width
        const y = (e.clientY - r.top) / r.height
        el.style.transform = `rotateY(${(x - 0.5) * 10}deg) rotateX(${(0.5 - y) * 8}deg) translateZ(0)`
        el.style.setProperty('--gx', `${x * 100}%`)
        el.style.setProperty('--gy', `${y * 100}%`)
      })
      el.addEventListener('pointerleave', () => { el.style.transform = '' })
    })
  }

  /* ---------- 3D coverflow of screenshots ---------- */
  $$('.coverflow').forEach((flow) => {
    const items = $$('figure', flow)
    const wrap = flow.parentElement
    const caption = $('.cf-caption', wrap)
    const dots = $('.cf-dots', wrap)
    if (!items.length) return
    let index = 0
    items.forEach((_, i) => { const b = document.createElement('button'); b.type = 'button'; b.setAttribute('aria-label', `Screenshot ${i + 1}`); b.addEventListener('click', () => { stop(); go(i) }); dots?.append(b) })
    const go = (i) => {
      index = (i + items.length) % items.length
      items.forEach((f, n) => {
        let d = n - index
        if (d > items.length / 2) d -= items.length
        if (d < -items.length / 2) d += items.length
        const a = Math.abs(d)
        f.classList.toggle('active', d === 0)
        f.style.zIndex = String(100 - a)
        f.style.opacity = a > 2 ? '0' : String(1 - a * 0.22)
        f.style.filter = a ? `brightness(${1 - a * 0.2})` : ''
        f.style.pointerEvents = a > 2 ? 'none' : ''
        f.style.transform = `translateX(${d * 42}%) translateZ(${-a * 240}px) rotateY(${-Math.sign(d) * Math.min(a, 2) * 28}deg)`
      })
      if (dots) [...dots.children].forEach((b, n) => b.classList.toggle('on', n === index))
      if (caption) { $('h3', caption).textContent = items[index].dataset.title || ''; $('p', caption).textContent = items[index].dataset.text || '' }
    }
    items.forEach((f, n) => f.addEventListener('click', () => n !== index && (stop(), go(n))))
    $$('[data-cf]', wrap).forEach((b) => b.addEventListener('click', () => { stop(); go(index + Number(b.dataset.cf)) }))
    flow.addEventListener('keydown', (e) => { if (e.key === 'ArrowRight') go(index + 1); if (e.key === 'ArrowLeft') go(index - 1) })
    let startX = null
    flow.addEventListener('pointerdown', (e) => { startX = e.clientX; stop() })
    flow.addEventListener('pointerup', (e) => { if (startX === null) return; const dx = e.clientX - startX; if (Math.abs(dx) > 40) go(index + (dx < 0 ? 1 : -1)); startX = null })
    let auto = reduced ? 0 : setInterval(() => go(index + 1), 4200)
    function stop() { clearInterval(auto); auto = 0 }
    go(0)
  })

  /* ---------- Light / dark compare slider ---------- */
  $$('.compare').forEach((c) => { const r = $('input', c); r?.addEventListener('input', () => c.style.setProperty('--pos', `${r.value}%`)) })

  /* ---------- Count-up numbers ---------- */
  const counters = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (!e.isIntersecting) continue
      counters.unobserve(e.target)
      const el = e.target
      const end = Number(el.dataset.count)
      const pre = el.dataset.prefix ?? ''
      const post = el.dataset.suffix ?? ''
      if (reduced || end < 5) continue
      const t0 = performance.now()
      const tick = (t) => { const k = Math.min(1, (t - t0) / 1400); el.textContent = `${pre}${Math.round(end * (1 - Math.pow(1 - k, 3)))}${post}`; if (k < 1) requestAnimationFrame(tick) }
      requestAnimationFrame(tick)
    }
  }, { threshold: 0.6 })
  $$('[data-count]').forEach((el) => counters.observe(el))

  /* ---------- Product doors: a carousel once they don't all fit; industry chips filter them ---------- */
  $$('[data-doors]').forEach((wrap) => {
    const track = $('.door-track', wrap)
    const doors = $$('.door', track)
    const dots = $('.door-dots', wrap)
    const prev = $('[data-door-prev]', wrap)
    const next = $('[data-door-next]', wrap)
    track.toggleAttribute('data-many', doors.length > 2)
    const visible = () => doors.filter((d) => !d.hidden)
    const step = () => (visible()[0]?.offsetWidth || 1) + parseFloat(getComputedStyle(track).columnGap || '0')
    const go = (i) => track.scrollTo({ left: Math.max(0, i) * step(), behavior: reduced ? 'auto' : 'smooth' })
    const drawDots = () => { if (!dots) return; dots.innerHTML = visible().map((d, i) => `<button type="button" aria-label="Go to card ${i + 1}"></button>`).join(''); [...dots.children].forEach((b, i) => b.addEventListener('click', () => go(i))) }
    const update = () => {
      wrap.classList.toggle('scrolls', track.scrollWidth > track.clientWidth + 2)
      const at = Math.round(track.scrollLeft / step())
      if (dots) [...dots.children].forEach((d, i) => d.toggleAttribute('aria-current', i === at))
      if (prev) prev.disabled = track.scrollLeft < 4
      if (next) next.disabled = track.scrollLeft + track.clientWidth > track.scrollWidth - 4
    }
    prev?.addEventListener('click', () => go(Math.round(track.scrollLeft / step()) - 1))
    next?.addEventListener('click', () => go(Math.round(track.scrollLeft / step()) + 1))
    track.addEventListener('scroll', () => requestAnimationFrame(update), { passive: true })
    addEventListener('resize', update)
    const chips = $$('[data-door-chips] button')
    const filter = (ind) => {
      chips.forEach((c) => { const on = c.dataset.industry === ind; c.classList.toggle('on', on); c.setAttribute('aria-pressed', String(on)) })
      doors.forEach((d) => (d.hidden = !(ind === '*' || d.dataset.industry === ind || d.dataset.industry === '*')))
      track.scrollLeft = 0
      drawDots(); update()
    }
    chips.forEach((c) => c.addEventListener('click', () => filter(c.dataset.industry)))
    const want = new URLSearchParams(location.search).get('industry')
    if (want && chips.some((c) => c.dataset.industry === want)) filter(want)
    else { drawDots(); update() }
  })

  /* ---------- FAQ with topics and search ---------- */
  $$('.faq2').forEach((faq) => {
    const items = $$('details.qa', faq)
    const tabs = $$('.faq-topics button', faq)
    const search = $('[data-faq-search]', faq)
    const empty = $('.faq-empty', faq)
    let topic = 'popular'
    $$('[data-topic-count]', faq).forEach((s) => { const t = s.dataset.topicCount; s.textContent = String(items.filter((i) => (t === 'popular' ? i.hasAttribute('data-popular') : i.dataset.topic === t)).length) })
    const text = new Map(items.map((i) => [i, i.textContent.toLowerCase()]))
    const show = () => {
      const q = (search?.value || '').trim().toLowerCase()
      let shown = 0
      for (const i of items) {
        const on = q ? text.get(i).includes(q) : topic === 'popular' ? i.hasAttribute('data-popular') : i.dataset.topic === topic
        i.hidden = !on
        if (on) shown++
        else i.open = false
      }
      if (empty) empty.hidden = shown > 0
    }
    const pick = (t) => { if (t) topic = t; tabs.forEach((x) => { const on = x.dataset.topic === t; x.classList.toggle('on', on); x.setAttribute('aria-selected', String(on)) }) }
    tabs.forEach((b) => b.addEventListener('click', () => { pick(b.dataset.topic); if (search) search.value = ''; show() }))
    search?.addEventListener('input', () => { pick(search.value.trim() ? '' : topic || 'popular'); show() })
    items.forEach((i) => i.addEventListener('toggle', () => i.open && items.forEach((x) => x !== i && (x.open = false))))
    pick('popular'); show()
    const first = items.find((i) => !i.hidden)
    if (first) first.open = true
  })

  /* ---------- Back to top ---------- */
  $$('[data-to-top]').forEach((b) => b.addEventListener('click', () => scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' })))

  /* ---------- Small notice at the bottom of the screen ---------- */
  let toast, toastTimer
  const showToast = (iconId, text, linkText, href) => {
    if (!toast) { toast = document.createElement('div'); toast.className = 'toast'; toast.setAttribute('role', 'status'); document.body.append(toast) }
    toast.innerHTML = `<svg class="i" aria-hidden="true"><use href="#i-${iconId}"/></svg><span>${text}</span>${linkText ? `<a href="${href}">${linkText}</a>` : ''}`
    requestAnimationFrame(() => toast.classList.add('is-on'))
    clearTimeout(toastTimer)
    toastTimer = setTimeout(() => toast.classList.remove('is-on'), 5000)
  }

  /* ---------- Placeholders until the real links are set in site-data.js ---------- */
  $$('[data-download-pending]').forEach((a) => a.addEventListener('click', (e) => {
    e.preventDefault()
    showToast('download', 'The download is coming soon. Meanwhile, we’ll set it up for you in a free demo.', 'Book a demo', toFile(root + 'contact/?interest=demo'))
  }))
  $$('[data-wa-pending]').forEach((a) => a.addEventListener('click', (e) => {
    e.preventDefault()
    showToast('message', 'Our WhatsApp line is coming soon. Send us a message here and we’ll reply within a working day.', 'Contact us', toFile(root + 'contact/'))
  }))
  // "Talk to us" style links: WhatsApp when a number is set, otherwise the contact page.
  $$('[data-whatsapp]').forEach((a) => {
    if (C.whatsapp) {
      const text = a.dataset.whatsapp || 'Hi CraftedSoft! I have a question about your software.'
      a.href = `https://wa.me/${C.whatsapp}?text=${encodeURIComponent(text)}`
      a.target = '_blank'
      a.rel = 'noopener'
    } else a.href = toFile(root + 'contact/')
  })

  /* ---------- Floating WhatsApp button ---------- */
  const fab = $('.wa-fab')
  if (fab) {
    const num = fab.dataset.wa
    if (num) {
      const product = document.title.split('·')[0].trim()
      const msg = (document.body.dataset.page || '').startsWith('product-') ? `Hi CraftedSoft! I'd like to know more about ${product}.` : 'Hi CraftedSoft! I have a question about your software.'
      fab.href = `https://wa.me/${num}?text=${encodeURIComponent(msg)}`
    }
    let peeked = false
    try { peeked = sessionStorage.getItem('cs-wa-peek') === '1' } catch (e) { /* storage blocked */ }
    if (!peeked && !reduced && hoverable) {
      setTimeout(() => {
        fab.classList.add('is-peek')
        try { sessionStorage.setItem('cs-wa-peek', '1') } catch (e) { /* ignore */ }
        setTimeout(() => fab.classList.remove('is-peek'), 4500)
      }, 5000)
    }
  }

  /* ---------- Analytics events (only if an analytics service is set in site-data.js) ---------- */
  const track = (name) => {
    try {
      if (typeof window.plausible === 'function') window.plausible(name, { props: { page: location.pathname } })
      if (typeof window.gtag === 'function') window.gtag('event', name.toLowerCase().replace(/\s+/g, '_'), { page_path: location.pathname })
    } catch (e) { /* never let analytics break the page */ }
  }
  document.addEventListener('click', (e) => {
    const a = e.target.closest && e.target.closest('a, button')
    if (!a) return
    if (a.dataset.track) return track(a.dataset.track)
    if (a.matches('.btn-dl, .door-dl, [data-download-pending]')) return track('Download')
    const href = a.getAttribute('href') || ''
    if (/contact\/(index\.html)?\?interest=demo/.test(href) || /book a (free )?demo/i.test(a.textContent)) return track('Book demo')
    if (/contact\/(index\.html)?\?interest=custom/.test(href)) return track('Custom project')
  })

  /* ---------- Legal pages: highlight the section being read ---------- */
  const tocLinks = $$('.legal-toc a')
  if (tocLinks.length) {
    const byId = new Map(tocLinks.map((a) => [a.getAttribute('href').slice(1), a]))
    const lio = new IntersectionObserver((entries) => {
      entries.forEach((en) => { if (!en.isIntersecting) return; tocLinks.forEach((a) => a.classList.remove('is-active')); byId.get(en.target.id)?.classList.add('is-active') })
    }, { rootMargin: '-30% 0px -60% 0px' })
    byId.forEach((_, id) => { const s = document.getElementById(id); if (s) lio.observe(s) })
  }

  /* ---------- Contact form: builds a WhatsApp message (or an email) from the answers ---------- */
  const form = $('#contact-form')
  if (form) {
    const qs = new URLSearchParams(location.search)
    const interests = $$('input[name="interest"]', form)
    const productGroup = $('#product-group')
    const syncProduct = () => { if (productGroup) productGroup.hidden = form.elements.interest?.value === 'Custom software' }
    interests.forEach((r) => r.addEventListener('change', syncProduct))
    const want = qs.get('interest')
    if (want) {
      const map = { custom: 'Custom software', demo: 'Product demo', pricing: 'Pricing', support: 'Support' }
      const target = map[want.toLowerCase()] || want
      const r = interests.find((x) => x.value.toLowerCase() === target.toLowerCase())
      if (r) r.checked = true
    }
    syncProduct()
    const product = qs.get('product')
    if (product) {
      const pills = $$('input[name="product"]', form).filter((x) => x.value)
      const r = pills.find((x) => x.value === product) || pills.find((x) => product.toLowerCase().startsWith(x.value.toLowerCase()))
      if (r) {
        r.checked = true
        if (r.value !== product) { const h = document.createElement('input'); h.type = 'hidden'; h.name = 'productDetail'; h.value = product; form.append(h) }
      }
    }
    const note = $('#form-note')
    form.addEventListener('submit', (e) => {
      e.preventDefault()
      track('Contact form')
      const d = Object.fromEntries(new FormData(form))
      let ok = true
      ;['name', 'phone'].forEach((k) => {
        const el = form.elements[k]
        if (!el) return
        const bad = !String(d[k] || '').trim() || (k === 'phone' && String(d[k]).replace(/\D/g, '').length < 10)
        el.setAttribute('aria-invalid', bad ? 'true' : 'false')
        if (bad) ok = false
      })
      if (!ok) { if (note) { note.textContent = 'Please add your name and a 10-digit mobile number.'; note.className = 'form-note is-err' } return }
      const text = [
        `Hi CraftedSoft, I'm interested in: ${d.interest || 'your software'}${d.product && d.interest !== 'Custom software' ? ` (${d.productDetail || d.product})` : ''}.`,
        `Name: ${d.name}`,
        d.business && `Business: ${d.business}`,
        `Mobile: ${d.phone}`,
        d.city && `City: ${d.city}`,
        d.message && `\n${d.message}`
      ].filter(Boolean).join('\n')
      if (C.whatsapp) window.open(`https://wa.me/${C.whatsapp}?text=${encodeURIComponent(text)}`, '_blank', 'noopener')
      else location.href = `mailto:${C.email}?subject=${encodeURIComponent(`${d.interest || 'Enquiry'}: ${d.business || d.name}`)}&body=${encodeURIComponent(text)}`
      if (note) { note.textContent = 'Thank you! Your message is ready to send. We reply within one working day.'; note.className = 'form-note is-ok' }
    })
  }
})()
